  const KEY = 'parley.prefs.v1';
  function saved() { try { return JSON.parse(localStorage.getItem(KEY) || '{}'); } catch (e) { return {}; } }
  function detect() { const s = saved().ui; if (s && D[s]) return s; const nav = (navigator.language || 'en').slice(0, 2).toLowerCase(); return D[nav] ? nav : 'en'; }
  let lang = detect();
  function t(key) { return (D[lang] && D[lang][key]) || D.en[key] || key; }
  function apply(root) {
    root = root || document;
    root.querySelectorAll('[data-i18n]').forEach((n) => { n.textContent = t(n.getAttribute('data-i18n')); });
    root.querySelectorAll('[data-i18n-html]').forEach((n) => { n.innerHTML = t(n.getAttribute('data-i18n-html')); });
    root.querySelectorAll('[data-i18n-ph]').forEach((n) => { n.placeholder = t(n.getAttribute('data-i18n-ph')); });
    document.documentElement.lang = lang;
    document.querySelectorAll('[data-ui-lang]').forEach((n) => { n.value = lang; });
  }
  function set(code) { if (!D[code]) return; lang = code; try { const p = saved(); p.ui = code; localStorage.setItem(KEY, JSON.stringify(p)); } catch (e) {} apply(); document.dispatchEvent(new CustomEvent('i18n:change', { detail: { lang } })); }
  return { get lang() { return lang; }, t, apply, set, LANGS, has: (c) => !!D[c] };
